/** Direct polygon rendering, matching the V3 prototype coordinate system.
 * Geometry is cached in four meshes. No client-only classes enter server logic.
 */
public final class SkarapeyaRenderer extends EntityRenderer<Skarapeya> {
 private static final ResourceLocation WHITE=ResourceLocation.withDefaultNamespace("textures/block/white_concrete.png");
 private static final int DARK=0x332720,BROWN=0x59402D,GOLD=0xD5A13C,BRONZE=0xA77830,BELLY=0xC6A16B,SKIN=0xD2A887,HAIR=0x272124,HAIR2=0x463331,WOOD=0x533421,BONE=0xEEE0B6,GREEN=0x9FE632,BLADE=0xE2CC93,MOUTH=0x47202A;
 private record Face(Vec3[] points,int color,int group,int string){}
 private static final class Mesh {final List<Face> faces=new ArrayList<>();int group=0,string=-1;
  void quad(int color,Vec3...p){faces.add(new Face(p,color,group,string));}
  void box(double x,double y,double z,double X,double Y,double Z,int c){Vec3 a=v(x,y,z),b=v(X,y,z),d=v(x,Y,z),e=v(X,Y,z),f=v(x,y,Z),g=v(X,y,Z),h=v(x,Y,Z),i=v(X,Y,Z);quad(c,a,b,e,d);quad(c,f,h,i,g);quad(c,a,f,g,b);quad(c,d,e,i,h);quad(c,a,d,h,f);quad(c,b,g,i,e);}
  void rod(Vec3 a,Vec3 b,double radius,int c){tube(new Vec3[]{a,b},new double[]{radius,radius},2,8,c,false);}
  void tube(Vec3[] p,double[] radii,int steps,int sides,int c,boolean pattern){
   Vec3[][] rings=new Vec3[steps+1][sides];
   for(int i=0;i<=steps;i++){double t=i/(double)steps;Vec3 at=curve(p,t),dir=curve(p,Math.min(1,t+.002)).subtract(curve(p,Math.max(0,t-.002))).normalize();if(dir.lengthSqr()<.001)dir=v(0,0,1);Vec3 down=v(0,-Math.abs(dir.z),-(1-Math.abs(dir.z)));down=down.subtract(dir.scale(dir.dot(down))).normalize();if(down.lengthSqr()<.001)down=dir.cross(v(1,0,0)).normalize();Vec3 side=dir.cross(down).normalize();double r=sample(radii,t);
    for(int j=0;j<sides;j++){double a=2*Math.PI*j/sides-Math.PI;Vec3 q=at.add(down.scale(Math.cos(a)*r)).add(side.scale(Math.sin(a)*r));rings[i][j]=pattern?v(q.x,q.y,Math.max(.1,q.z)):q;}}
   for(int i=0;i<steps;i++)for(int j=0;j<sides;j++){int k=(j+1)%sides,col=c;double a=Math.abs(2*Math.PI*(j+.5)/sides-Math.PI);if(pattern){if(a<.94)col=i%4==0?0xA88050:BELLY;else if((i/6+(a>2?1:0))%6==0)col=(i+j)%4==0?BRONZE:GOLD;else if(a<1.6&&(i/3+j)%12<2)col=0x537E26;else if((i+j)%5==0)col=BROWN;}quad(col,rings[i][j],rings[i][k],rings[i+1][k],rings[i+1][j]);}
   for(int j=0;j<sides;j++){int k=(j+1)%sides;quad(c,p[0],rings[0][k],rings[0][j],p[0]);quad(c,p[p.length-1],rings[steps][j],rings[steps][k],p[p.length-1]);}
  }
 }
 private static Vec3 v(double x,double y,double z){return new Vec3(x,y,z);}
 private static double mix(double a,double b,double t){return a+(b-a)*t;}
 private static double sample(double[] a,double t){double f=Math.clamp(t,0,1)*(a.length-1);int i=Math.min(a.length-2,(int)f);return mix(a[i],a[i+1],f-i);}
 private static double keyed(double[] x,double[] y,double at){int i=0;while(i<x.length-2&&at>x[i+1])i++;return mix(y[i],y[i+1],Math.clamp((at-x[i])/(x[i+1]-x[i]),0,1));}
 private static Vec3 curve(Vec3[] p,double t){double f=Math.clamp(t,0,1)*(p.length-1);int i=Math.min(p.length-2,(int)f);double s=f-i,s2=s*s,s3=s2*s;Vec3 a=p[Math.max(0,i-1)],b=p[i],c=p[i+1],d=p[Math.min(p.length-1,i+2)];return b.scale(2).add(c.subtract(a).scale(s)).add(a.scale(2).subtract(b.scale(5)).add(c.scale(4)).subtract(d).scale(s2)).add(a.scale(-1).add(b.scale(3)).subtract(c.scale(3)).add(d).scale(s3)).scale(.5);}
 private static void tail(Mesh m,boolean snake){List<Vec3> p=new ArrayList<>(List.of(v(12,12,2.1),v(25,16,3.8),v(29,4,5.4),v(23,-11,5.8),v(7,-17,6.1),v(-11,-15,6.2),v(-25,-5,6.3),v(-26,12,6.4),v(-11,21,6.4),v(6,19,6.8),v(15,10,7.3),v(12,0,8.5),v(5,-4,12.5),v(1,-5,18),v(0,-5,24)));if(snake)p.addAll(List.of(v(0,-4,30),v(0,-6,37),v(0,-10,42)));else p.add(v(0,-5,26));m.tube(p.toArray(Vec3[]::new),snake?new double[]{.65,3.7,5.7,6.2,6.6,6.1,5.8,4.4}:new double[]{.65,3.8,5.7,6.3,6.5,6,4.5,3.9},128,24,DARK,true);}
 private static void hood(Mesh m){double[] z={23,26,30,34,38,41,44,45},w={4.4,8.5,13.8,18,18.5,15,8,4.5};Vec3[][] p=new Vec3[29][33];for(int i=0;i<29;i++){double h=23+22*i/28D,ww=keyed(z,w,h);for(int j=0;j<33;j++){double x=ww*(j/16D-1);p[i][j]=v(x,keyed(new double[]{23,32,40,45},new double[]{-2,-1,-3,-6},h)+.014*x*x+Math.abs(x)*.13,h);}}for(int i=0;i<28;i++)for(int j=0;j<32;j++){Vec3 q=p[i][j];double eye=Math.pow((Math.abs(q.x)-11.3)/4.3,2)+Math.pow((q.z-35.8)/6.6,2);int c=Math.abs(j/16D-1)>.91||eye>.82&&eye<1.53?GOLD:eye<.23?GREEN:(i/3+j/3)%7==0?BROWN:DARK;m.quad(c,p[i][j],p[i+1][j],p[i+1][j+1],p[i][j+1]);}}
 private static Mesh cobra(){Mesh m=new Mesh();tail(m,true);hood(m);m.box(-6,-18,42,6,-8,45,BROWN);m.box(-5,-22,42,5,-15,44,DARK);m.box(-5,-20,41,5,-12,42,MOUTH);m.group=4;m.box(-5,-20,36,5,-9,38,BELLY);m.box(-4,-21,38,4,-14,39,BROWN);m.box(-4,-19,39,4,-12,40,MOUTH);m.group=0;for(int s:new int[]{-1,1}){m.box(s*5-1,-18,44,s*5+1,-17,45,GOLD);m.box(s*5-1,-18.2,44,s*5+1,-18,44.8,GREEN);m.box(s*4-.4,-20,39,s*4+.4,-19,42,BONE);m.rod(v(s*5,-8,45),v(s*8,-7,48),.8,GOLD);m.rod(v(s*3,-10,46),v(s*4,-9,49),.8,GOLD);}m.box(-3,-12,46,3,-8,47,GOLD);m.box(-1,-12,48,1,-10,50,GOLD);m.box(-.5,-13,48,.5,-12,50,GREEN);return m;}
 private static void torso(Mesh m){double[] k={23,26,29,31.5,34,35.6,37.1,38.2,39.3,41},rx={4.6,5.5,4.5,3.5,4.8,6.4,6.1,5,2.3,1.55},dep={3.9,3.7,3.1,2.7,4.9,6.2,5.5,2.9,1.7,1.5},cy={-5,-5,-5,-5,-5.6,-6.4,-5.8,-5,-5,-5};Vec3[][] p=new Vec3[37][32];for(int i=0;i<=36;i++){double z=23+i*.5;for(int j=0;j<32;j++){double a=2*Math.PI*j/32-Math.PI;p[i][j]=v(keyed(k,rx,z)*Math.sin(a),keyed(k,cy,z)-keyed(k,dep,z)*Math.cos(a),z);}}for(int i=0;i<36;i++)for(int j=0;j<32;j++){double z=23+i*.5,a=2*Math.PI*j/32-Math.PI;int c=z<28.8?DARK:SKIN;if(z<28.8&&(Math.abs(a)<.95||z>26&&z<26.7))c=z>26&&z<26.7?GOLD:BROWN;if(z>33.65&&z<37.05&&Math.abs(a)<1.7)c=z<34.15||z>36.65||Math.abs(a)<.14?GOLD:DARK;m.quad(c,p[i][j],p[i][(j+1)%32],p[i+1][(j+1)%32],p[i+1][j]);}m.box(-1,-13,35,1,-12,36,GOLD);m.box(-.5,-14,35,.5,-13,36,GREEN);}
 private static void hair(Mesh m){for(int i=-5;i<=5;i++){double x=i*.89;m.tube(new Vec3[]{v(x,-1.6,48),v(x*1.22,1,43),v(x*1.65,3.5,37),v(x*1.95,4.5,25+Math.abs(i)%4*2)},new double[]{1.3,1.25,1.05,.65},16,8,i%2==0?HAIR2:HAIR,false);}for(int s:new int[]{-1,1}){for(int i=0;i<4;i++)m.tube(new Vec3[]{v(s*(3.4+i*.4),-3.8+i*.35,48),v(s*(5.1+i*.7),-4.1+i*.8,43),v(s*(6.3+i*.6),-3.6+i*.8,37),v(s*(6.4+i*.85),-1.6+i*.8,29+i%3*3)},new double[]{1.1,1.2,1.05,.55},16,8,i%2==0?HAIR:HAIR2,false);for(int i=0;i<3;i++)m.tube(new Vec3[]{v(s*(3.8+i*.35),-6.1+i*.25,47),v(s*(4.7+i*.55),-8+i*.6,42),v(s*(5.8+i*.65),-8.7+i*.65,37),v(s*(5.9+i*.6),-7.9+i*.65,31+i*2)},new double[]{1.1,1,.9,.48},16,8,i==1?HAIR:HAIR2,false);}}
 private static void head(Mesh m){m.box(-1,-6,39,1,-4,42,SKIN);m.box(-3.5,-8,43,3.5,-2,49,SKIN);m.box(-2.5,-8,41,2.5,-3,43,SKIN);m.box(-3.5,-8,48,3.5,-2,49.5,HAIR);m.box(-3.4,-8,43,-2.8,-2,48,HAIR);m.box(2.8,-8,43,3.4,-2,48,HAIR);m.box(-2.5,-8.2,47,2.5,-8,48,HAIR);for(int s:new int[]{-1,1}){m.box(s*2-.5,-8.04,45,s*2+.5,-8,46,GREEN);m.box(s-.3,-8.09,42,s+.3,-8,43,BONE);m.rod(v(s*3,-4,49),v(s*7,-4,52),.8,GOLD);m.rod(v(s*7,-4,52),v(s*8,-4,55),.7,GOLD);m.rod(v(s*4,-3,50),v(s*9,-3,49),.7,GOLD);m.rod(v(s*9,-3,49),v(s*10,-3,51),.7,GOLD);m.rod(v(s*9,-3,49),v(s*9,-3,46),.35,BRONZE);m.box(s*9-.5,-3.5,45,s*9+.5,-2.5,46,GREEN);}m.box(-1,-8.06,43,1,-8,44,MOUTH);m.box(-3.5,-9,49,3.5,-7,50,GOLD);m.box(-1,-8,51,1,-6,53,GOLD);m.box(-.5,-9,51,.5,-8,52,GREEN);hair(m);}
 private static void bladeMesh(Mesh m,Vec3 a,Vec3 b,boolean joined){Vec3 t=b.subtract(a).normalize(),n=v(-t.z,0,t.x);m.rod(a,b,.85,WOOD);for(double u:new double[]{.12,.4,.6,.88}){Vec3 q=a.lerp(b,u);m.box(q.x-1.1,q.y-1.1,q.z-1.1,q.x+1.1,q.y+1.1,q.z+1.1,GOLD);}Vec3[] spiral=new Vec3[31];for(int i=0;i<31;i++){double u=i/30D;spiral[i]=a.lerp(b,u).add(n.scale(Math.sin(u*6*Math.PI)*1.1)).add(0,Math.cos(u*6*Math.PI)*1.1,0);}m.tube(spiral,new double[]{.65,.65},30,6,BRONZE,false);for(int s:joined?new int[]{-1,1}:new int[]{1}){Vec3 p=s==1?b:a,d=t.scale(s),nn=v(-d.z,0,d.x);m.tube(new Vec3[]{p.subtract(d.scale(3)).add(nn),p.add(nn.scale(2)),p.add(d.scale(3)).add(nn.scale(2.7)),p.add(d.scale(6)).add(nn),p.add(d.scale(7)).subtract(nn.scale(1.5))},new double[]{1.6,2,1.6,.6},22,10,GOLD,false);m.tube(new Vec3[]{p.add(nn.scale(3)),p.add(d.scale(3)).add(nn.scale(4)),p.add(d.scale(6)).add(nn.scale(2)),p.add(d.scale(8)).subtract(nn.scale(1.5))},new double[]{.75,.9,.8,.4},20,8,BLADE,false);Vec3 q=p.add(nn.scale(1.8));m.box(q.x-.6,q.y-1.7,q.z-.6,q.x+.6,q.y-1,q.z+.6,GREEN);}}
 private static Vec3 instrument(double x,double z,double d){return v(x,-16+z*.78+d,33+z*.72);}
 private static void gusli(Mesh m){double[][] outline={{-10,-4},{-8,-5},{6,-5},{10,-3},{10,2},{8,5},{-7,6},{-10,3}};Vec3 middle=instrument(0,0,0);for(int i=0;i<outline.length;i++){double[] a=outline[i],b=outline[(i+1)%outline.length];Vec3 x=instrument(a[0],a[1],0),y=instrument(b[0],b[1],0);m.quad(WOOD,middle,x,y,middle);m.quad(WOOD,x,y,y.add(0,1.3,0),x.add(0,1.3,0));m.rod(x,y,.38,GOLD);}for(int i=0;i<7;i++){double z=-3.4+i*1.04;Vec3 a=instrument(-7.8,z,-.75),b=instrument(7.6,z,-.75);m.string=i;m.rod(a,b,.135,GOLD);m.string=-1;for(Vec3 q:new Vec3[]{a,b})m.box(q.x-.5,q.y-.5,q.z-.5,q.x+.5,q.y+.5,q.z+.5,GOLD);}for(int s:new int[]{-1,1}){m.tube(new Vec3[]{v(s*9,-15,34),v(s*10.4,-15,36.5),v(s*10,-15,39),v(s*8.6,-15.5,39.8)},new double[]{1,1.15,1.05,.8},16,8,GOLD,false);m.box(s*8.7-1.2,-17,39,s*8.7+1.2,-14,40,DARK);m.box(s*8.7-.5,-18,39,s*8.7+.5,-17,40,GREEN);}m.box(-.6,-21,27,.6,-20,28,GREEN);}
 private static Mesh human(int mode){Mesh m=new Mesh();tail(m,false);torso(m);head(m);for(int s:new int[]{-1,1}){m.group=s<0?1:2;Vec3 shoulder=v(s*5,-5,37),elbow=mode==1?v(s*10,-7,33):mode==2?v(s*10,-5,32):v(s*9,-9,32),hand=mode==1?v(s*7,-14,33):mode==2?v(s*14,-10,34):v(s*(s<0?9:2),-17,s<0?33:34);m.tube(new Vec3[]{shoulder,elbow,hand},new double[]{1.8,1.45,1.25},16,12,SKIN,false);m.rod(shoulder,shoulder.add(0,0,-1.5),2.1,GOLD);m.rod(hand.lerp(elbow,.28),hand,1.65,GOLD);m.box(hand.x-1.3,hand.y-1.3,hand.z-1.3,hand.x+1.3,hand.y+1.3,hand.z+1.3,SKIN);if(mode==2)bladeMesh(m,v(s*14,-10,28),v(s*20,-10,45),false);}m.group=3;if(mode==1)bladeMesh(m,v(-21,-14,33),v(21,-14,33),true);if(mode==3)gusli(m);return m;}
 private static final class Holder {static final Mesh[] M={cobra(),human(1),human(2),human(3)};}
 public SkarapeyaRenderer(EntityRendererProvider.Context c){super(c);shadowRadius=2.2F;}
 @Override public ResourceLocation getTextureLocation(Skarapeya e){return WHITE;}
 @Override public boolean shouldRender(Skarapeya e,Frustum f,double x,double y,double z){return f.isVisible(e.getBoundingBox().inflate(9,4,9));}
 private static Vec3 rotate(Vec3 p,Vec3 pivot,double a,boolean vertical){Vec3 d=p.subtract(pivot);double c=Math.cos(a),s=Math.sin(a);return pivot.add(vertical?v(d.x*c-d.y*s,d.x*s+d.y*c,d.z):v(d.x,d.y*c-d.z*s,d.y*s+d.z*c));}
 private static Vec3 pose(Vec3 p,int group,Skarapeya e,double t){int a=e.action();double strike=Math.sin(Math.PI*Math.max(0,(t-.2)/.8)),h=Math.clamp((p.z-13)/29,0,1);if(e.phase()==1){if(a==BITE||a==GRAB){p=p.add(0,-h*15*strike,-h*10*strike);if(group==4)p=rotate(p,v(0,-10,38),-.35*strike,false);}else if(a==COIL||a==RING){double k=1-.30*strike*Math.clamp((18-p.z)/15,0,1);p=v(p.x*k,p.y*k-10*strike*Math.clamp((18-p.z)/15,0,1),p.z);}else if(a==TAIL){double k=Math.clamp((12-p.z)/10,0,1)*Math.clamp((p.x+10)/34,0,1);p=rotate(p,Vec3.ZERO,1.7*strike*k,true);}else if(a==CHARGE)p=p.add(0,-6*strike,-h*16*strike);else if(a==SPIT)p=p.add(0,-h*4*strike,h*5*strike);}else if(e.weapon()==1){double angle=(a==SPIN?2.7:a==SLASH?1.48:-.61)*strike;Vec3 r=rotate(p,v(0,-5,30),angle,a!=BLADE_WAVE);p=p.lerp(r,Math.clamp((p.z-21)/11,0,1));}else if(e.weapon()==2&&group>0&&group<3){int s=group==1?-1:1;double k=group==1?strike:Math.sin(Math.PI*Math.max(0,(t-.36)/.64));p=rotate(p,v(s*5,-5,37),s*1.13*k,true);}else if(e.weapon()==3&&group==2)p=rotate(p,v(5,-5,37),.14*Math.sin((e.tickCount+t)*.55),false);return v(p.x*.125,p.z*.125,-p.y*.125);}
 @Override public void render(Skarapeya e,float yaw,float partial,PoseStack stack,MultiBufferSource buffer,int light){int mode=e.weapon();if(e.action()==TRANSFORM&&e.age()<30)mode=0;Mesh mesh=Holder.M[mode];double t=e.action()==IDLE?0:Math.clamp((e.age()+partial)/LENGTH[e.action()],0,1);stack.pushPose();stack.mulPose(Axis.YP.rotationDegrees(-yaw));var out=buffer.getBuffer(RenderType.entityCutoutNoCull(WHITE));var ps=stack.last();int overlay=e.hurtTime>0?OverlayTexture.pack(0,OverlayTexture.v(true)):OverlayTexture.NO_OVERLAY;for(Face f:mesh.faces){Vec3[] p=new Vec3[4];for(int i=0;i<4;i++)p[i]=pose(f.points[i],f.group,e,t);Vec3 normal=p[1].subtract(p[0]).cross(p[2].subtract(p[0])).normalize();if(normal.lengthSqr()<.0001)continue;int c=f.color;boolean lit=c==GREEN;if(f.string>=0){lit=f.string==e.first()||f.string==e.second();c=lit?COLOR[f.string]:GOLD;}else if(c==GREEN&&mode>0)c=COLOR[e.first()];int packed=lit?LightTexture.FULL_BRIGHT:light;for(int i=0;i<4;i++)out.addVertex(ps.pose(),(float)p[i].x,(float)p[i].y,(float)p[i].z).setColor(0xFF000000|c).setUv(i==0||i==3?0:1,i<2?0:1).setOverlay(overlay).setLight(packed).setNormal(ps,(float)normal.x,(float)normal.y,(float)normal.z);}stack.popPose();super.render(e,yaw,partial,stack,buffer,light);}
}
